////  CityViewModel.swift//  YP_Trains//import SwiftUIimport Combineclass CityViewModel: ObservableObject {    @Published var searchText = ""    @Published var allCities: [CityModel] = []    @Published var filteredCities: [CityModel] = []        // Используем @ObservedObject для кэш-менеджера    @ObservedObject private var cacheManager = CachedDataManager.shared        private let yaApiKey = Config.shared.getApiKey()        init() {        loadCities()    }        private func loadCities() {        // Проверяем наличие кэша и его свежести        if cacheManager.isDataCached(), cacheManager.isCacheFresh() {            if let cachedCities = cacheManager.getCachedCities() {                self.allCities = cachedCities                self.filteredCities = cachedCities                print("Loaded cities from cache: \(cachedCities.count)")            }        } else {            // Если кэш пуст или устарел, загружаем с API            fetchAllStations()        }    }    private func fetchAllStations() {        Task {            do {                let urlString = "https://api.rasp.yandex.net/v3.0/stations_list/?apikey=\(yaApiKey)&format=json"                                guard let url = URL(string: urlString) else {                    print("Ошибка: неверный URL")                    return                }                                print("Fetching allStations via URLSession...")                                let (data, response) = try await URLSession.shared.data(from: url)                                guard let httpResponse = response as? HTTPURLResponse,                      httpResponse.statusCode == 200 else {                    print("Ошибка: сервер вернул не 200")                    return                }                                let model = try JSONDecoder().decode(AllStationModel.self, from: data)                                let allSettlements = model.countries                    .filter { $0.title == "Россия" }                    .flatMap { country in                        country.regions.flatMap { region in                            region.settlements                        }                    }                                let cities = allSettlements.map { CityModel(from: $0) }                                // Удаляем дубликаты                var uniqueCities: [CityModel] = []                var seenTitles = Set<String>()                                for city in cities {                    let uniqueKey = "\(city.title)_\(city.yandexCode ?? "nil")"                                        if !seenTitles.contains(uniqueKey) {                        seenTitles.insert(uniqueKey)                        uniqueCities.append(city)                    }                }                                // Сортируем по алфавиту                let sortedCities = uniqueCities.sorted { $0.title < $1.title }                                // Сохраняем в кэш                cacheManager.saveCities(sortedCities)                                await MainActor.run {                    self.allCities = sortedCities                    self.filteredCities = sortedCities                    print("Successfully loaded \(sortedCities.count) cities in Russia.")                }                            } catch {                print("Error fetching or decoding allStations: \(error)")            }        }    }    func filterCities() {        if searchText.isEmpty {            filteredCities = allCities        } else {            filteredCities = allCities.filter {                $0.title.localizedCaseInsensitiveContains(searchText)            }        }    }    func clearSearch() {        searchText = ""        filterCities()    }}